=== FILE: skid_buffer.v ===
`timescale 1ns/1ps
`default_nettype none
// skid_buffer: register slice for one valid/ready stream.
// Implements microarchitecture.md sections 2-3; ports per interface_spec.md.
module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    // Skid register: holds the newer of two beats.
    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    // s_ready is the inverse of a flop (interface_spec section 4).
    assign s_ready = ~skid_valid;

    wire m_free;   // the output register may load on this edge
    wire s_fire;   // an upstream beat is accepted on this edge
    assign m_free = ~m_valid | m_ready;
    assign s_fire = s_valid & s_ready;

    // Next state (microarchitecture section 3).
    reg             m_valid_d;
    reg [WIDTH-1:0] m_data_d;
    reg             skid_valid_d;
    reg [WIDTH-1:0] skid_data_d;

    always @* begin
        m_valid_d    = m_valid;
        m_data_d     = m_data;
        skid_valid_d = skid_valid;
        skid_data_d  = skid_data;
        if (m_free) begin
            if (skid_valid) begin
                // the skid beat moves to the output register
                m_valid_d    = 1'b1;
                m_data_d     = skid_data;
                skid_valid_d = 1'b0;
            end else begin
                // load the input straight into the output register
                m_valid_d    = s_valid;
                m_data_d     = s_data;
            end
        end else if (s_fire) begin
            // output stalled: catch the beat in the skid register
            skid_valid_d = 1'b1;
            skid_data_d  = s_data;
        end
    end

    // Control flops: synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else begin
            m_valid    <= m_valid_d;
            skid_valid <= skid_valid_d;
        end
    end

    // Data flops: not reset (microarchitecture section 2).
    always @(posedge clk) begin
        m_data    <= m_data_d;
        skid_data <= skid_data_d;
    end

`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Start in reset.
    always @(*) if (!f_past_valid) assume(!rst_n);

    // Reference queue of up to two beats, moved only by port handshakes.
    reg [1:0]       f_count;
    reg [WIDTH-1:0] f_q0;
    reg [WIDTH-1:0] f_q1;
    wire f_push;
    wire f_pop;
    assign f_push = s_valid & s_ready;
    assign f_pop  = m_valid & m_ready;

    always @(posedge clk) begin
        if (!rst_n) begin
            f_count <= 2'd0;
        end else begin
            case ({f_push, f_pop})
                2'b10: begin
                    if (f_count == 2'd0) f_q0 <= s_data;
                    else                 f_q1 <= s_data;
                    f_count <= f_count + 2'd1;
                end
                2'b01: begin
                    f_q0    <= f_q1;
                    f_count <= f_count - 2'd1;
                end
                2'b11: begin
                    if (f_count == 2'd2) begin
                        f_q0 <= f_q1;
                        f_q1 <= s_data;
                    end else begin
                        f_q0 <= s_data;
                    end
                end
                default: ;
            endcase
        end
    end

    // The ports behave as the queue; the skid register holds the newer beat.
    always @(*) if (f_past_valid) begin
        assert(f_count <= 2'd2);
        assert(m_valid == (f_count != 2'd0));
        assert(s_ready == (f_count != 2'd2));
        assert(!skid_valid || m_valid);
        if (f_count != 2'd0) assert(m_data == f_q0);
        if (f_count == 2'd2) assert(skid_data == f_q1);
    end

    // Hold: a stalled beat stays offered with the same data.
    always @(posedge clk)
        if (f_past_valid && $past(rst_n) && $past(m_valid) && !$past(m_ready))
            assert(m_valid && (m_data == $past(m_data)));

    // Cover support.
    reg       f_was_full;
    reg [2:0] f_tp;
    always @(posedge clk) begin
        if (!rst_n) begin
            f_was_full <= 1'b0;
            f_tp       <= 3'd0;
        end else begin
            if (skid_valid) f_was_full <= 1'b1;
            if (f_push && f_pop) begin
                if (f_tp != 3'd7) f_tp <= f_tp + 3'd1;
            end else begin
                f_tp <= 3'd0;
            end
        end
    end

    always @(posedge clk) if (f_past_valid && rst_n) begin
        cover(m_valid && !m_ready);        // stall
        cover(skid_valid);                 // full slice
        cover(f_was_full && !m_valid);     // drain after full
        cover(f_tp == 3'd4);               // full throughput
    end
`endif

endmodule
`default_nettype wire
=== END FILE ===
