`timescale 1ns/1ps
// Self-checking testbench for skid_buffer: WIDTH 8 and WIDTH 1 lanes.
module skid_buffer_tb;

    reg        clk;
    reg        rst_n;
    reg        s_valid;
    reg  [7:0] s_data;
    reg        m_ready;

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire [0:0] s_data1;
    wire [0:0] m_data1;

    assign s_data1 = s_data[0:0];

    skid_buffer #(.WIDTH(8)) dut8 (
        .clk(clk), .rst_n(rst_n),
        .s_valid(s_valid), .s_ready(s_ready8), .s_data(s_data),
        .m_valid(m_valid8), .m_ready(m_ready), .m_data(m_data8)
    );

    skid_buffer #(.WIDTH(1)) dut1 (
        .clk(clk), .rst_n(rst_n),
        .s_valid(s_valid), .s_ready(s_ready1), .s_data(s_data1),
        .m_valid(m_valid1), .m_ready(m_ready), .m_data(m_data1)
    );

    integer        passed;
    integer        failed;
    integer        cnt;          // reference queue occupancy
    reg [7:0]      q0;           // oldest beat
    reg [7:0]      q1;           // newer beat
    reg            model_ok;     // a reset edge has been seen
    integer        sent;
    integer        received;
    integer        dropped;
    reg            last_push;
    reg            last_pop;
    reg [31:0]     rng;
    reg [8*64-1:0] nonce;
    integer        i;
    integer        tp_cycles;
    integer        ready_hi_cycles;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    task check;
        input   cond;
        input integer id;
        begin
            if (cond === 1'b1) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("check %0d failed at time %0t (model count %0d)", id, $time, cnt);
            end
        end
    endtask

    task next_rand;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    task check_outputs;
        begin
            check(m_valid8 == (cnt != 0), 1);
            check(s_ready8 == (cnt != 2), 2);
            if (cnt != 0) check(m_data8 == q0, 3);
            check(m_valid1 == (cnt != 0), 4);
            check(s_ready1 == (cnt != 2), 5);
            if (cnt != 0) check(m_data1 == q0[0:0], 6);
        end
    endtask

    // Called at posedge+1 with inputs already set; returns at the next posedge+1.
    task cycle;
        reg       sv_s;
        reg       mr_s;
        reg [7:0] sd_s;
        reg       sr_ref;
        reg       mv_ref;
        reg [7:0] md_ref;
        reg       push;
        reg       pop;
        reg       rst_s;
        reg       hold_chk;
        reg [7:0] hold_d;
        reg [7:0] sd_e;
        begin
            #2;
            if (model_ok) begin
                check_outputs;
                // Outputs must not move with inputs inside a cycle.
                sv_s   = s_valid;
                mr_s   = m_ready;
                sd_s   = s_data;
                sr_ref = s_ready8;
                mv_ref = m_valid8;
                md_ref = m_data8;
                m_ready = ~mr_s;
                #1;
                check((s_ready8 == sr_ref) && (s_ready1 == sr_ref), 20);
                check((m_valid8 == mv_ref) && (!mv_ref || (m_data8 == md_ref)), 21);
                s_valid = ~sv_s;
                s_data  = ~sd_s;
                #1;
                check((s_ready8 == sr_ref) && (s_ready1 == sr_ref), 22);
                check((m_valid8 == mv_ref) && (!mv_ref || (m_data8 == md_ref)), 23);
                s_valid = sv_s;
                m_ready = mr_s;
                s_data  = sd_s;
                #1;
            end else begin
                #3;
            end
            rst_s    = rst_n;
            sd_e     = s_data;
            push     = s_valid && (cnt < 2);
            pop      = m_ready && (cnt > 0);
            hold_chk = model_ok && rst_n && m_valid8 && !m_ready;
            hold_d   = m_data8;
            @(posedge clk);
            #1;
            last_push = 1'b0;
            last_pop  = 1'b0;
            if (!rst_s) begin
                dropped  = dropped + (model_ok ? cnt : 0);
                cnt      = 0;
                model_ok = 1'b1;
            end else if (model_ok) begin
                last_push = push;
                last_pop  = pop;
                if (push) sent = sent + 1;
                if (pop)  received = received + 1;
                if (hold_chk) begin
                    check((m_valid8 == 1'b1) && (m_data8 == hold_d), 24);
                    check((m_valid1 == 1'b1) && (m_data1 == hold_d[0:0]), 25);
                end
                case ({push, pop})
                    2'b10: begin
                        if (cnt == 0) q0 = sd_e;
                        else          q1 = sd_e;
                        cnt = cnt + 1;
                    end
                    2'b01: begin
                        q0  = q1;
                        cnt = cnt - 1;
                    end
                    2'b11: begin
                        if (cnt == 1) begin
                            q0 = sd_e;
                        end else begin
                            q0 = q1;
                            q1 = sd_e;
                        end
                    end
                    default: ;
                endcase
            end
        end
    endtask

    initial begin
        passed    = 0;
        failed    = 0;
        cnt       = 0;
        q0        = 8'h00;
        q1        = 8'h00;
        model_ok  = 1'b0;
        sent      = 0;
        received  = 0;
        dropped   = 0;
        last_push = 1'b0;
        last_pop  = 1'b0;
        rng       = 32'h1234_5678;
        tp_cycles = 0;
        ready_hi_cycles = 0;
        rst_n     = 1'b0;
        s_valid   = 1'b0;
        s_data    = 8'h00;
        m_ready   = 1'b0;
        nonce     = {(8*64){1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {(8*64){1'b0}};

        @(posedge clk);
        #1;

        // 1. Reset values.
        cycle; cycle; cycle;
        check((m_valid8 == 1'b0) && (m_valid1 == 1'b0), 30);
        check((s_ready8 == 1'b1) && (s_ready1 == 1'b1), 31);
        rst_n = 1'b1;
        cycle;
        check((m_valid8 == 1'b0) && (s_ready8 == 1'b1), 32);

        // 2. One-cycle latency.
        m_ready = 1'b1;
        s_valid = 1'b1;
        s_data  = 8'hA5;
        check(m_valid8 == 1'b0, 33);
        cycle;
        check((m_valid8 == 1'b1) && (m_data8 == 8'hA5) && (m_valid1 == 1'b1) && (m_data1 == 1'b1), 34);
        s_valid = 1'b0;
        cycle;
        check((m_valid8 == 1'b0) && (m_valid1 == 1'b0), 35);

        // 3. Long stream at full throughput.
        s_valid = 1'b1;
        m_ready = 1'b1;
        tp_cycles = 0;
        ready_hi_cycles = 0;
        for (i = 0; i < 64; i = i + 1) begin
            s_data = i[7:0];
            if (s_ready8 == 1'b1) ready_hi_cycles = ready_hi_cycles + 1;
            cycle;
            if ((i > 0) && last_push && last_pop) tp_cycles = tp_cycles + 1;
            check((m_valid8 == 1'b1) && (m_data8 == i[7:0]), 36);
        end
        check(tp_cycles == 63, 37);
        check(ready_hi_cycles == 64, 38);
        s_valid = 1'b0;
        cycle;
        cycle;
        check(m_valid8 == 1'b0, 39);

        // 4. Stall with one beat held, then two.
        m_ready = 1'b0;
        s_valid = 1'b1;
        s_data  = 8'h11;
        cycle;
        check((m_valid8 == 1'b1) && (m_data8 == 8'h11) && (s_ready8 == 1'b1) && (s_ready1 == 1'b1), 40);
        s_data = 8'h22;
        cycle;
        check((m_valid8 == 1'b1) && (m_data8 == 8'h11) && (s_ready8 == 1'b0) && (s_ready1 == 1'b0), 41);
        s_data = 8'h33;
        for (i = 0; i < 3; i = i + 1) begin
            cycle;
            check((m_valid8 == 1'b1) && (m_data8 == 8'h11) && (s_ready8 == 1'b0) && (m_data1 == 1'b1), 42);
        end
        // 5. Ready rises after the stall: every beat out in order, once.
        m_ready = 1'b1;
        cycle;
        check((m_valid8 == 1'b1) && (m_data8 == 8'h22) && (s_ready8 == 1'b1) && (m_data1 == 1'b0), 43);
        cycle;
        check((m_valid8 == 1'b1) && (m_data8 == 8'h33) && (m_data1 == 1'b1), 44);
        s_valid = 1'b0;
        cycle;
        check((m_valid8 == 1'b0) && (s_ready8 == 1'b1), 45);
        check(sent == (received + dropped), 46);

        // 6. Single-cycle drop of m_ready in a stream.
        s_valid = 1'b1;
        for (i = 0; i < 8; i = i + 1) begin
            s_data  = 8'h80 + i[7:0];
            m_ready = (i != 3);
            cycle;
        end
        s_valid = 1'b0;
        m_ready = 1'b1;
        cycle;
        cycle;
        check((m_valid8 == 1'b0) && (sent == (received + dropped)), 47);

        // 7. Random traffic against the model, with occasional reset.
        for (i = 0; i < 3000; i = i + 1) begin
            next_rand;
            case (i[9:8])
                2'b00:   m_ready = rng[0] | rng[1];
                2'b01:   m_ready = rng[0] & rng[1];
                2'b10:   m_ready = rng[0];
                default: m_ready = 1'b1;
            endcase
            s_valid = rng[2] | rng[3];
            s_data  = rng[15:8];
            rst_n   = (rng[31:22] != 10'd0);
            cycle;
        end
        // Drain.
        rst_n   = 1'b1;
        s_valid = 1'b0;
        m_ready = 1'b1;
        cycle;
        cycle;
        cycle;
        check((cnt == 0) && (m_valid8 == 1'b0) && (s_ready8 == 1'b1) && (m_valid1 == 1'b0), 50);
        check(sent == (received + dropped), 51);
        check(sent > 1000, 52);

        // 8. Reset with beats held.
        m_ready = 1'b0;
        s_valid = 1'b1;
        s_data  = 8'h5A;
        cycle;
        s_data  = 8'hC3;
        cycle;
        check((m_valid8 == 1'b1) && (s_ready8 == 1'b0), 53);
        rst_n = 1'b0;
        cycle;
        check((m_valid8 == 1'b0) && (s_ready8 == 1'b1) && (m_valid1 == 1'b0) && (s_ready1 == 1'b1), 54);
        rst_n   = 1'b1;
        s_valid = 1'b0;
        m_ready = 1'b1;
        cycle;
        check(m_valid8 == 1'b0, 55);
        s_valid = 1'b1;
        s_data  = 8'h77;
        cycle;
        check((m_valid8 == 1'b1) && (m_data8 == 8'h77) && (m_data1 == 1'b1), 56);
        s_valid = 1'b0;
        cycle;
        check(m_valid8 == 1'b0, 57);
        check(sent == (received + dropped), 58);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
